#!/usr/bin/env python3
"""Generate dataclasses from schema/*.json."""
import json
import sys
from pathlib import Path

out = Path(sys.argv[sys.argv.index("--out") + 1])
lines = ["# @generated by tools/gen.py", "from dataclasses import dataclass", ""]
for f in sorted(Path("schema").glob("*.json")):
    lines.append("@dataclass")
    lines.append(f"class {f.stem.capitalize()}:")
    for name, spec in json.loads(f.read_text()).items():
        lines.append(f"    {name}: {spec['type']}")
out.write_text("\n".join(lines) + "\n")
